    sources: [{ label: 'Card: Squad Commander (ZNR #41) — Creature — Kor Warrior, 플레이버 없음, 한국어판 \'부대 지휘관\'', url: 'https://scryfall.com/card/znr/41/ko' }, { label: 'Zendikar: Things Have Changed (2020-09-01) — \'this region is now called the Makindi Trenches\'', url: 'https://magic.wizards.com/en/news/feature/zendikar-things-have-changed-2020-09-01' }, { label: 'Magic Story: The Red Route (Miguel Lopez, 2020-09-04) — \'They\'re Skyclave. From the kor that run the Trenches in Ondu\'', url: 'https://magic.wizards.com/en/news/magic-story/red-route-2020-09-04' }, { label: 'Plane Shift: Zendikar (2016) — Kor', url: 'https://media.wizards.com/2016/downloads/magic/Plane%20Shift%20Zendikar.pdf' }],
