    typeLine: 'Creature — Human Warrior',
    url: 'https://scryfall.com/card/znr/141/goma-fada-vanguard',
    image: 'https://cards.scryfall.io/normal/front/c/e/ce83962b-445a-4b44-ad8a-fada2c0a15b8.jpg?1783929359',
