    sources: [{ label: 'Card: Kargan Intimidator (ZNR #145) 한국어판 \'카르간 위협자\' — 플레이버 없음', url: 'https://scryfall.com/card/znr/145/ko' }, { label: 'Zendikar: Things Have Changed (Ari Zirulnik·James Wyatt, 2020-09-01) — \'the Kargan tribes mastered the dragons of Akoum and rode them to victory against the kor, shattering the Akoum Skyclave\'', url: 'https://magic.wizards.com/en/news/feature/zendikar-things-have-changed-2020-09-01' }, { label: 'Card: Kargan Warleader (ZNR #224) 한국어판', url: 'https://scryfall.com/card/znr/224/ko' }, { label: 'Card: Tormenting Voice (ZNR #172) 한국어판 — \'Kargan tribal lands\'', url: 'https://scryfall.com/card/znr/172/ko' }],
