    sources: [{ label: 'Card: Cragplate Baloth (ZNR #183) — Creature — Beast, 플레이버 없음, 한국어판 \'암석갑옷 발로스\'', url: 'https://scryfall.com/card/znr/183/cragplate-baloth' }, { label: 'Plane Shift: Zendikar (James Wyatt, 2016) p.33 Baloths — \'The leatherback baloths of Ora Ondar are heavier and keep to the ground, where their thick, plated hide protects them from danger.\'', url: 'https://media.wizards.com/2016/downloads/magic/Plane%20Shift%20Zendikar.pdf' }],
