    sources: [{ label: 'Card: Tajuru Paragon (ZNR #209) — Creature — Elf, \'Tajuru Paragon is also a Cleric, Rogue, Warrior, and Wizard.\', 플레이버 없음, 한국어판 \'타주루 귀감\'', url: 'https://scryfall.com/card/znr/209/tajuru-paragon' }, { label: 'Card: Tajuru Snarecaster (ZNR #210) — \'Elves of the Tajuru Nation spend their lives in the ancient jaddi trees\' expansive canopy\'', url: 'https://scryfall.com/card/znr/210/tajuru-snarecaster' }, { label: 'Reclamation (2016-01-06) — 무라사의 타주루 땅', url: 'https://magic.wizards.com/en/news/feature/reclamation-2016-01-06' }],
